export type Fixture = { stable: unknown[]; assessment: unknown[] };
export function set(
  v: Fixture,
  path: number[],
  value: unknown,
  stable = false,
) {
  let node = stable ? v.stable : v.assessment;
  for (const index of path.slice(0, -1)) node = node[index] as unknown[];
  node[path.at(-1)!] = value;
}
export function get(v: Fixture, path: number[], stable = false): unknown {
  let node: unknown = stable ? v.stable : v.assessment;
  for (const index of path) node = (node as unknown[])[index];
  return node;
}
export function fixture(action = 'initialize', state = 'absent'): Fixture {
  const v: Fixture = {
    stable: JSON.parse(stableBase),
    assessment: JSON.parse(assessmentBase),
  };
  v.stable[2] = action;
  if (state === 'unassessed')
    v.assessment[2] = [
      'unassessed',
      '0',
      null,
      null,
      null,
      null,
      null,
      '2026-01-01T00:00:00.000Z',
    ];
  if (state === 'selected') {
    v.stable[6] = 'fictional-v0';
    v.stable[7] = '9007199254740993';
    v.assessment[2] = [
      'selected',
      v.stable[7],
      v.stable[6],
      false,
      'BDT',
      'fictional-units-v1',
      2,
      '2026-01-01T00:00:00.000Z',
    ];
    v.assessment[4] = JSON.parse(JSON.stringify(v.assessment[3]));
    set(v, [4, 0, 0], 'fictional-v0');
    v.assessment[5] = [...(get(v, [4, 1, 0]) as unknown[])];
  }
  if (action === 'adopt')
    (v.assessment[7] as unknown[][]).push([
      'adoption',
      '30000000-0000-4000-8000-000000000003',
      'currency-adoption-v1',
      'c'.repeat(64),
    ]);
  return bind(v);
}
export function bind(v: Fixture) {
  const intent = encodeCurrencySelectionIntent(JSON.stringify(v.stable));
  assert.ok(intent.success, 'Expected valid fictional S syntax');
  v.assessment[1] = intent.stableIntentDigest;
  return v;
}
export function canonical(
  v: Fixture,
  rawStable = JSON.stringify(v.stable),
  rawAssessment = JSON.stringify(v.assessment),
) {
  const s = encodeCurrencySelectionIntent(rawStable);
  const a = encodeCurrencySelectionAssessment(rawStable, rawAssessment);
  assert.ok(
    s.success && a.success,
    'Expected valid fictional canonical syntax',
  );
  return {
    success: true,
    stableCanonicalText: s.canonicalText,
    canonicalText: a.canonicalText,
    stableIntentDigest: s.stableIntentDigest,
    assessmentDigest: a.assessmentDigest,
  };
}

