export function manyContext(
  count: number,
  revision = 'fictional-v1',
  maximal = false,
): unknown[] {
  const units: unknown[][] = [];
  const caps: unknown[][] = [];
  const version = maximal ? 'v'.repeat(64) : 'fictional-v1';
  for (let i = 0; i < count; i++) {
    const code = `A${String.fromCharCode(65 + Math.floor(i / 26))}${String.fromCharCode(65 + (i % 26))}`;
    units.push([
      code,
      version,
      i % 5,
      maximal ? '\\'.repeat(256) : 'Fictional source',
      'current',
    ]);
    caps.push([code, version, true, false, false]);
  }
  return [[revision, ['AAA', version], ['AAA', version], null, caps], units];
}
export function largestFixture() {
  const v = fixture('replace', 'selected');
  v.stable[6] = 'a'.repeat(64);
  v.stable[8] = 'z'.repeat(64);
  v.stable[7] = '9223372036854775807';
  v.assessment[3] = manyContext(32, v.stable[8] as string, true);
  v.assessment[4] = manyContext(32, v.stable[6] as string, true);
  v.assessment[5] = [...(get(v, [4, 1, 0]) as unknown[])];
  v.assessment[2] = [
    'selected',
    v.stable[7],
    v.stable[6],
    false,
    'AAA',
    'v'.repeat(64),
    0,
    '0000-02-29T23:59:59.999Z',
  ];
  set(v, [6, 5], '9223372036854775807');
  set(v, [6, 7], '9223372036854775807');
  set(v, [6, 8], 'recovery');
  set(v, [6, 9], 'ffffffff-ffff-ffff-ffff-ffffffffffff');
  const roots = v.assessment[7] as unknown[][];
  for (let i = 2; i < 32; i++)
    roots.push([
      'history',
      `30000000-0000-4000-8000-${String(i + 1).padStart(12, '0')}`,
      'currency-history-assessment-v1',
      'b'.repeat(64),
    ]);
  return bind(v);
}

export function positiveFixtures(): Fixture[] {
  const fixtures: Fixture[] = [];
  for (const action of ['initialize', 'adopt'])
    for (const state of ['absent', 'unassessed'])
      fixtures.push(fixture(action, state));
  for (const latch of [false, true]) {
    const v = fixture('replace', 'selected');
    set(v, [2, 3], latch);
    fixtures.push(v);
  }
  for (const date of [
    '0000-01-01T00:00:00.000Z',
    '0000-02-29T23:59:59.999Z',
    '2000-02-29T00:00:00.001Z',
    '1900-02-28T12:34:56.789Z',
    '9999-12-31T23:59:59.999Z',
  ]) {
    const v = fixture('initialize', 'unassessed');
    set(v, [2, 7], date);
    fixtures.push(v);
  }
  for (let exponent = 0; exponent <= 4; exponent++) {
    const v = fixture();
    set(v, [3, 1, 0, 2], exponent);
    fixtures.push(v);
  }
  for (const source of [
    'Exact "quote" \\ provenance',
    '!' + ' '.repeat(254) + '~',
    '"'.repeat(256),
    '\\'.repeat(256),
  ]) {
    const v = fixture();
    set(v, [3, 1, 0, 3], source);
    fixtures.push(v);
  }
  for (const uuid of [
    '00000000-0000-0000-0000-000000000000',
    'ffffffff-ffff-ffff-ffff-ffffffffffff',
    ...Array.from(
      { length: 8 },
      (_, i) => `a0b1c2d3-0000-${i + 1}000-8000-abcd12345678`,
    ),
  ]) {
    for (const path of [[1, 0], [1, 1], [3], [4], [5]]) {
      const v = fixture();
      set(v, path, uuid, true);
      if (path[0] === 1 && path[1] === 1) set(v, [6, 1], uuid);
      if (path[0] === 3) set(v, [6, 2], uuid);
      if (path[0] === 4) set(v, [6, 4], uuid);
      fixtures.push(bind(v));
    }
  }
  for (const position of [0, 3, 6, 9]) {
    const v = fixture();
    if (position === 9) set(v, [6, 8], 'recovery');
    set(v, [6, position], 'ffffffff-ffff-ffff-ffff-ffffffffffff');
    fixtures.push(v);
  }
  for (const position of [5, 7])
    for (const counter of ['9007199254740993', '9223372036854775807']) {
      const v = fixture();
      set(v, [6, position], counter);
      fixtures.push(v);
    }
  for (const display of [false, true])
    for (const newSales of [false, true])
      for (const collection of [false, true]) {
        const v = fixture();
        const ctx = get(v, [3]) as unknown[][];
        (ctx[0]![4] as unknown[][]).push([
          'USD',
          'fictional-units-v1',
          true,
          true,
          true,
        ]);
        ctx[1]!.push([
          'USD',
          'fictional-units-v1',
          2,
          'Fictional source',
          'current',
        ]);
        ctx[0]![2] = ['USD', 'fictional-units-v1'];
        set(v, [3, 0, 4, 0, 2], display);
        set(v, [3, 0, 4, 0, 3], newSales);
        set(v, [3, 0, 4, 0, 4], collection);
        if (!display && !newSales) set(v, [3, 1, 0, 4], 'historical');
        fixtures.push(v);
        if (display) {
          const second = structuredClone(v);
          set(second, [3, 0, 3], ['BDT', 'fictional-units-v1']);
          fixtures.push(second);
        }
      }
  // False latch permits a new base; true latch permits new metadata, not new code/exponent.
  for (const latch of [false, true]) {
    const v = fixture('replace', 'selected');
    set(v, [2, 3], latch);
    const code = latch ? 'BDT' : 'USD';
    for (const path of [
      [3, 0, 1],
      [3, 0, 2],
      [3, 0, 4, 0],
      [3, 1, 0],
    ]) {
      set(v, [...path, 0], code);
      set(v, [...path, 1], 'New:version._-1');
    }
    fixtures.push(v);
  }
  const caseRevision = fixture();
  caseRevision.stable[8] = 'Fictional:V1._-';
  set(caseRevision, [3, 0, 0], caseRevision.stable[8]);
  fixtures.push(bind(caseRevision));
  const alternatePrior = fixture('replace', 'selected');
  set(alternatePrior, [2, 3], true);
  for (const path of [
    [4, 0, 1, 1],
    [4, 0, 2, 1],
    [4, 0, 4, 0, 1],
    [4, 1, 0, 1],
  ])
    set(alternatePrior, path, 'New:version._-1');
  fixtures.push(alternatePrior);
  fixtures.push(largestFixture());
  return fixtures;
}

